effect.shader:
// tempo do Node ligado ao motor (tools/nodevideo/ligar_tempo.py)
#define _cur_time acTime
// globais do Node ligados ao motor (tools/nodevideo/ligar_globais.py)
#define _resolution acTamanhoDaTela
vec4 u_xlat0;
vec4 u_xlat1;
vec4 u_xlat2;
bvec2 u_xlatb2;
vec4 u_xlat3;
vec4 u_xlat4;
vec4 u_xlat5;
float u_xlat14;
vec2 u_xlat16;
float u_xlat18;
bool u_xlatb18;
float u_xlat20;
float u_xlat21;
bool u_xlatb21;
void main()
{
    u_xlat0.xyz = _color.xyz * vec3(0.305306017, 0.305306017, 0.305306017) + vec3(0.682171106, 0.682171106, 0.682171106);
    u_xlat0.xyz = _color.xyz * u_xlat0.xyz + vec3(0.0125228781, 0.0125228781, 0.0125228781);
    u_xlat0.xyz = u_xlat0.xyz * _color.xyz;
    u_xlat1 = texture(inputImg, acScreenNorm.xy);
    u_xlat18 = _resolution.x / _resolution.y;
    u_xlat2.x = u_xlat18 * acScreenNorm.x;
    u_xlat2.y = acScreenNorm.y;
    u_xlat2.xy = u_xlat2.xy + vec2(-0.5, -0.5);
    u_xlat18 = _angle * 0.0174532924;
    u_xlat3.x = sin(u_xlat18);
    u_xlat4.x = cos(u_xlat18);
    u_xlat5.x = sin((-u_xlat18));
    u_xlat5.y = u_xlat4.x;
    u_xlat4.x = dot(u_xlat5.yx, u_xlat2.xy);
    u_xlat5.z = u_xlat3.x;
    u_xlat4.y = dot(u_xlat5.zy, u_xlat2.xy);
    u_xlat2.xy = u_xlat4.xy * _scale.xy + _offset.xy;
    u_xlat2.xy = u_xlat2.xy + vec2(0.5, 0.5);
    u_xlat18 = _iteration * 10.0;
    u_xlat14 = _cur_time * _speed + 1.0;
    u_xlat3.x = float(0.0);
    u_xlat3.y = float(0.0);
    u_xlat3.z = float(0.0);
    u_xlat4.x = float(0.0);
    u_xlat4.y = float(0.0);
    u_xlat20 = 7.0;
    while(true){
        u_xlatb21 = u_xlat20>=u_xlat18;
        if(u_xlatb21){break;}
        u_xlat16.xy = vec2(u_xlat20) * u_xlat2.xy + vec2(u_xlat14);
        u_xlat16.xy = u_xlat4.yx * vec2(vec2(_distortion, _distortion)) + u_xlat16.xy;
        u_xlat16.xy = cos(u_xlat16.xy);
        u_xlat4.xy = u_xlat16.xy + u_xlat4.xy;
        u_xlat21 = dot(u_xlat4.xy, u_xlat4.xy);
        u_xlat21 = sqrt(u_xlat21);
        u_xlat20 = u_xlat20 * 1.33333337;
        u_xlat21 = u_xlat21 / u_xlat20;
        u_xlat3.xyz = vec3(u_xlat21) + u_xlat3.xyz;
    }
    u_xlat2.xyz = u_xlat3.xyz * vec3(0.305306017, 0.305306017, 0.305306017) + vec3(0.682171106, 0.682171106, 0.682171106);
    u_xlat2.xyz = u_xlat3.xyz * u_xlat2.xyz + vec3(0.0125228781, 0.0125228781, 0.0125228781);
    u_xlat2.xyz = u_xlat2.xyz * u_xlat3.xyz;
    u_xlat2.xyz = log2(u_xlat2.xyz);
    u_xlat2.xyz = u_xlat2.xyz * vec3(vec3(_contrast, _contrast, _contrast));
    u_xlat2.xyz = exp2(u_xlat2.xyz);
    u_xlat0.xyz = u_xlat0.xyz * u_xlat2.xyz;
    u_xlat0.xyz = u_xlat0.xyz * vec3(5.77078009, 5.77078009, 5.77078009);
    u_xlat2.xyz = exp2(u_xlat0.xyz);
    u_xlat0.xyz = exp2((-u_xlat0.xyz));
    u_xlat3.xyz = (-u_xlat0.xyz) + u_xlat2.xyz;
    u_xlat0.xyz = u_xlat0.xyz + u_xlat2.xyz;
    u_xlat0.xyz = vec3(1.0, 1.0, 1.0) / u_xlat0.xyz;
    u_xlat2.xyz = u_xlat0.xyz * u_xlat3.xyz;
    u_xlatb18 = int(_blend_mode)==1;
    u_xlat2.w = 1.0;
    u_xlat4 = u_xlat1 * u_xlat2;
    u_xlat3.xyz = u_xlat3.xyz * u_xlat0.xyz + u_xlat1.xyz;
    u_xlat3.w = u_xlat1.w;
    u_xlat0 = (bool(u_xlatb18)) ? u_xlat4 : u_xlat3;
    u_xlat3.xyz = u_xlat2.xyz;
    u_xlat0 = (int(_blend_mode) != 0) ? u_xlat0 : u_xlat3;
    if(int(_use_inner_mask) != 0) {
        u_xlatb2.xy = equal(ivec4(int(_show_inner_mask), int(_b_clip_mask), int(_show_inner_mask), int(_show_inner_mask)), ivec4(1, 1, 0, 0)).xy;
        u_xlat3 = (u_xlatb2.x) ? vec4(1.0, 0.0, 1.0, 1.0) : u_xlat0;
        u_xlat4 = texture(Mask, acScreenNorm.xy);
        u_xlat5 = (-u_xlat4) + vec4(1.0, 1.0, 1.0, 1.0);
        u_xlat1 = u_xlat1 * u_xlat5;
        u_xlat1 = u_xlat3 * u_xlat4 + u_xlat1;
        u_xlat2.x = u_xlat4.x * u_xlat1.w;
        fragColor.w = (u_xlatb2.y) ? u_xlat2.x : u_xlat1.w;
        fragColor.xyz = u_xlat1.xyz;
    } else {
        fragColor = u_xlat0;
    }
    return;
}
